contracts.source:
interface Props {
  open: boolean
  empresaNome: string
  /** `null` = todas ativas (ausência de override). */
  initial: string[] | null | undefined
  /** Módulos ativos — capacidade com dono off fica desativada. */
  modulos: string[] | null | undefined
  saving?: boolean
  onSave: (capacidades: string[] | null) => void
  onClose: () => void
}

export interface EmpresaFormInitial {
  nome: string
  documento?: string | null
  nomeFantasia?: string | null
  ativa: boolean
}

interface EmpresaFormProps {
  onSubmit: (data: EmpresaFormData) => void
  onCancel: () => void
  /** Presente = modo edição (esconde os campos de admin). */
  initial?: EmpresaFormInitial
}

interface EmpresaListProps {
  empresas: EmpresaComStats[]
  onConfigurar: (empresa: EmpresaComStats) => void
  onRecursos: (empresa: EmpresaComStats) => void
  onEditar: (empresa: EmpresaComStats) => void
}

interface FieldErrors {
  nome?: string
  email?: string
}

interface Props {
  editing: OperadorRow | null
  /** Possíveis chefes (admins + sócios da empresa) — apenas para admin/super. */
  chefes?: OperadorRow[]
  /** Role de quem está criando/gerenciando (admin/socio/super_admin). */
  actorRole?: "admin" | "socio" | "super_admin"
  onSubmit: (data: OperadorFormData) => Promise<void>
  onCancel: () => void
  /** Ações de conta (modo edição) — quando ausentes, a seção "Status da conta" não renderiza. */
  onAlterarStatus?: () => void
  onReenviarConvite?: () => void
  onRevogarConvite?: () => void
}

export interface OperadorFormHandle {
  submit: () => Promise<void>
}

export interface ReassignState {
  operador: OperadorRow
  roleDesejado: "admin" | "socio" | "operator"
  subordinados: number
}

interface Props {
  open: boolean
  reassign: ReassignState | null
  /** Chefes válidos (admins da empresa, excluindo o alvo). */
  chefes: OperadorRow[]
  saving?: boolean
  onConfirm: (novoChefeId: string) => void
  onClose: () => void
}

interface PerfilErros {
  novoEmail?: string
  senhaAlteracao?: string
}

interface AjustarCaixaModalProps {
  open: boolean
  onClose: () => void
  caixaBase: number
  saldoAtual: number
  /** Título contextual (ex.: "Ajustar Caixa Total" no caixa próprio · "Ajustar caixa base do operador" no operador). */
  title: string
  onAjustar: (valor: number, motivo: string) => Promise<void>
}

interface AjusteCaixaFormProps {
  caixaBase: number
  saldoAtual: number
  onAjustar: (valor: number, motivo: string) => Promise<void>
  onSuccess?: () => void
}

interface AjusteHistoricoProps {
  auditoria: AuditoriaCaixaItem[]
}

interface CaixaKpisProps {
  caixa: CaixaStatus
  /** Quais KPIs exibir (default: todos). Permite agrupar por seção (ex.: só "Hoje"). */
  kpis?: CaixaKpiKey[]
  /** Callbacks opcionais por KPI (ex.: abertura de modais). Sem cliques quando ausente. */
  onKpiClick?: Partial<Record<CaixaKpiKey, () => void>>
}

interface ContratosSemanaModalProps {
  open: boolean
  items: Contrato[]
  loading?: boolean
  onClose: () => void
}

interface MovimentacoesListProps {
  movimentacoes: MovimentacaoItem[]
}

interface Props {
  clienteId: string
}

interface ClienteCardProps {
  cliente: Cliente
  variant: "list-item" | "detail"
}

interface ClienteFormProps {
  /** Cliente a editar (null = novo). */
  initial?: Cliente | null
  /** Executa o create/update real (pode lançar ApiError). */
  onSubmit: (payload: Record<string, unknown>) => Promise<void>
  onCancel: () => void
}

type BlocoGps = {
  coords: { lat: number; lng: number } | null
  estado: GpsEstado
  origem: "gps" | "cep_aproximado" | null
  aviso: string | null
}

interface ClienteInfoProps {
  cliente: Cliente
}

interface SituacaoFinanceiraProps {
  cliente: Cliente
}

export interface ClienteResumoSelect {
  id: string
  nome: string
  telefone?: string
  bairro?: string
}

interface ClienteSelectProps {
  value: string | null
  onChange: (id: string) => void
  clientes: ClienteResumoSelect[]
  error?: string
}

interface ContratoCardProps {
  contrato: Contrato
  variant: "list-item" | "detail"
}

interface ContratoFormProps {
  mode: "novo" | "editar"
  /** Lista p/ o seletor buscável (novo). */
  clientes?: ClienteResumoSelect[]
  /** Cliente fixado (edit ou novo via ?clienteId=) — exibido em Card read-only. */
  clienteFixado?: { id: string; nome: string }
  initial?: Partial<ContratoFormData>
  onSubmit: (data: ContratoSubmit) => Promise<void>
  onCancel: () => void
}

interface ContratoInfoProps {
  contrato: Contrato
}

interface ParcelaListProps {
  parcelas: Parcela[]
  onPagar?: (parcela: Parcela) => void
}

interface GastoFormProps {
  onSuccess: () => void
}

interface GastoListProps {
  items: GastoItem[]
  totalPeriodo: number
  onDelete: (id: string) => void
}

interface CarteiraChartProps {
  carteira: CarteiraSnapshot
  ariaLabel: string
}

interface ContribuicaoChartProps {
  operadores: ContribuicaoOperador[]
  ariaLabel: string
}

interface GastosCategoriaChartProps {
  gastos: GastoCategoria[]
  ariaLabel: string
}

interface PrevistoRecebidoChartProps {
  serie: SerieItem[]
  /** aria-label descritivo (a11y — F1-f4). */
  ariaLabel: string
}

interface TendenciaChartProps {
  serie: SerieItem[]
  /** aria-label descritivo (a11y — F1-f4). */
  ariaLabel: string
}

type Estado =
  | { fase: "loading" }
  | { fase: "sucesso" }
  | { fase: "erro"; mensagem: string }
  | { fase: "tokenAusente" }

interface CobrancaCardProps {
  item: CobrancaItem
  onClick?: () => void
  className?: string
}

interface CobrancaListProps {
  items: CobrancaItem[]
  onCardClick?: (item: CobrancaItem) => void
  emptyMessageKey?: string
}

interface PagamentoCardProps {
  item: PagamentoDoDiaItem
  onClick?: () => void
  className?: string
}

interface PagamentosHojeModalProps {
  open: boolean
  items: PagamentoDoDiaItem[]
  loading?: boolean
  onClose: () => void
}

export interface PagamentoSuccessData {
  valor: number
  pagasRange: { inicio: number; fim: number } | null
  saldoRestante: number
}

interface PagamentoModalProps {
  contratoId: string
  valorSugerido: number
  saldoDevedor: number
  parcelaLabel?: string
  onClose: () => void
  onSuccess: (data: PagamentoSuccessData) => void
  /** PLAN-062: passo comprovante DENTRO do mesmo modal (modais 3→2). `fechar` fecha o modal. */
  sucessoContent?: (data: PagamentoSuccessData, fechar: () => void) => ReactNode
}

interface AuthContextType {
  user: AuthUser | null
  token: string | null
  login: (email: string, senha: string) => Promise<LoginResponse>
  logout: () => void
  loading: boolean
  /** Refaz GET /me e atualiza o usuário (ex.: após trocar a foto no Perfil). */
  refreshUser: () => Promise<void>
}

interface Props {
  mod: ModuleId
  children: ReactNode
}

interface AvatarProps {
  foto?: string | null
  nome: string
  size?: AvatarSize
  className?: string
  /** Clicar abre a foto ampliada (lightbox — PLAN-058). Só ativo quando há foto. */
  ampliar?: boolean
}

interface ButtonBaseProps {
  variant?: Variant
  size?: Size
}

interface ButtonLinkProps extends Omit<LinkProps, "className">, ButtonBaseProps {
  className?: string
}

interface CardTitleProps {
  children: ReactNode
  className?: string
}

interface CardHeaderProps {
  children: ReactNode
  className?: string
  border?: boolean
}

interface CardBodyProps {
  children: ReactNode
  className?: string
}

interface CardDotProps {
  color: "red" | "blue" | "green" | "yellow" | "gray"
  size?: "sm" | "md"
}

interface CardIndicatorProps {
  label: string
  value: string
}

interface CardIndicatorsProps {
  children: ReactNode
  className?: string
}

interface CardBadgeProps {
  variant: "success" | "warning" | "danger" | "info" | "neutral"
  label: string
}

interface CardActionsProps {
  actions: Array<{
    icon?: LucideIcon
    label: string
    onClick: () => void
    variant?: "blue" | "green" | "gray" | "warning" | "danger"
    show?: boolean
  }>
  layout?: "horizontal" | "vertical"
  disabled?: boolean
  size?: "sm" | "md"
}

interface ChartCardProps {
  /** Título do gráfico (i18n). */
  title: string
  className?: string
  /** Conteúdo do gráfico (ResponsiveContainer/Recharts) ou estados (EstadoTela). */
  children: ReactNode
}

interface CollapsibleSectionProps<T = unknown> {
  title: string
  /** Contagem exibida no header (ex.: total de itens). */
  count?: number
  /** Itens a listar (com `renderItem`) — habilita limite + "Ver mais". */
  items?: T[]
  renderItem?: (item: T) => ReactNode
  /** Máximo de itens antes do "Ver mais" (default: todos). */
  limit?: number
  /** Começa colapsada (default: false). */
  defaultCollapsed?: boolean
  /** Modo controlado (opcional): estado externo da expansão. Sem isso, o estado é interno. */
  open?: boolean
  /** Callback quando o usuário alterna (só usado no modo controlado). */
  onToggle?: (open: boolean) => void
  /** Conteúdo direto (quando não usa items/renderItem). */
  children?: ReactNode
  className?: string
}

interface ErrorBannerProps {
  message: string
  onRetry?: () => void
  onDismiss?: () => void
  className?: string
}

interface ErrorBoundaryProps {
  children: ReactNode
}

interface ErrorBoundaryState {
  hasError: boolean
  error: Error | null
}

interface EstadoTelaProps {
  loading: boolean
  error: string | null
  empty: boolean
  emptyMessage?: string
  emptyAction?: { label: string; to: string }
  onRetry?: () => void
  children: React.ReactNode
}

interface FieldProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string
  error?: string
  hint?: string
  right?: ReactNode
}

interface FieldSelectProps extends SelectHTMLAttributes<HTMLSelectElement> {
  label: string
  error?: string
  hint?: string
  /** Option placeholder (value vazio, disabled + hidden). */
  placeholder?: string
  options: Array<{ value: string; label: string }>
}

interface FieldTextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  label: string
  error?: string
  hint?: string
}

export interface LogoProps {
  /** `lg` (login/landing) · `sm` (sidebar/navbar) · `mono` (<= 24px, favicon) */
  variant?: MarkVariant
  /** desenha o quadrado preenchido de fundo (app icon / favicon, full-bleed) */
  boxed?: boolean
  className?: string
  title?: string
}

export interface LogoLockupProps {
  className?: string
  tagline?: boolean
  size?: "sm" | "md" | "lg"
}

interface PageHeaderProps {
  icon: LucideIcon
  title: string
  subtitle?: string
  /** linha pequena acima do título (ex.: data do dia) */
  eyebrow?: string
  action?: ReactNode
  back?: { onClick: () => void; title?: string }
}

interface QuickActionsProps {
  actions: QuickAction[]
  layout?: "horizontal" | "vertical" | "grid"
  disabled?: boolean
  size?: "sm" | "md"
  /** No layout "grid": força uma linha única com todas as ações visíveis (adaptável a itens ocultos). */
  singleRow?: boolean
}

interface SearchBarProps {
  value: string
  onChange: (value: string) => void
  placeholder?: string
  onClear?: () => void
}

interface SectionHeaderProps {
  title: string
  action?: { label: string; onClick: () => void }
}

interface Item<T extends string> {
  value: T
  label: string
  icon?: ReactNode
}

interface StatusBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant: Variant
  label: string
  size?: Size
}

interface SuccessStateProps {
  title: string
  detail?: string
  linkLabel?: string
  onLinkClick?: () => void
}

interface SwitchProps {
  checked: boolean
  onChange?: (v: boolean) => void
  disabled?: boolean
  label: string
  /** Tooltip exibido quando desabilitado (motivo). */
  motivo?: string
}

interface TabsProps<T extends string> {
  value: T
  onChange: (v: T) => void
  items: Array<{ value: T; label: string }>
  className?: string
}

export interface FabState {
  label: string
  to: string
}

interface FabContextType {
  fab: FabState | null
  setFab: (fab: FabState | null) => void
}

interface FeedbackOverlayProps {
  status: FeedbackStatus
  message: string
}

interface FeedbackState {
  status: FeedbackStatus
  message: string
}

interface RunOptions {
  loading: string
  success: string
  error: string
  action: () => Promise<void>
}

interface GpsControlProps {
  coords: Localizacao | null
  estado: GpsEstado
  capturando?: boolean
  /** Mensagem de erro já traduzida (permissão/indisponível). */
  erro?: string | null
  /** Aviso já traduzido (ex.: geocode sem endereço). */
  aviso?: string | null
  origem?: "gps" | "cep_aproximado" | null
  onCapturar: () => void
  className?: string
}

interface NavItem {
  to: string
  label: string
  icon: typeof Users
  end?: boolean
}

interface Aba {
  modulo?: ModuleId
  chave: ChaveNav
  to: string
  icon: LucideIcon
  /** rota exata (Central). As demais ativam por prefixo via NavLink. */
  end?: boolean
}

interface Item {
  chave: string
  icon: LucideIcon
  to?: string
  onClick?: () => void
}

interface UserMenuProps {
  /** desktop: exibe nome + papel ao lado do avatar (rodapé da sidebar) */
  detalhado?: boolean
  /** para onde o popover cresce no desktop (padrão: acima, rodapé da sidebar) */
  crescer?: "cima" | "baixo"
  className?: string
}

interface ThemeContextValue {
  /** Paleta ativa (default/violeta/ocean/grape/sunset). */
  palette: ThemeId
  /** Modo de tema: claro/escuro/sistema (preferência do SO). */
  mode: ThemeMode
  /** Escuro efetivo (derivado do modo). */
  isDark: boolean
  setPalette: (id: ThemeId) => void
  setMode: (m: ThemeMode) => void
  toggleDark: () => void
}

interface ThemeProviderProps {
  children: ReactNode
}

interface Options {
  empresaId?: string
  onSaved?: () => void
}

export interface EquipeResult {
  operadores: EquipeItem[]
  totais: { totalClientes: number; contratosAtivos: number; recebidoHoje: number }
}

export interface ImpactoModuloItem {
  modulo: string
  contagem: number
  bloqueia: boolean
  detalhe: string
}

export interface ImpactoDesativacao {
  desligados: string[]
  impacto: ImpactoModuloItem[]
  bloqueado: boolean
}

export interface LoginResponse {
  token: string
  usuario: UsuarioComum
}

export interface PaginatedResponse<T> {
  data: T[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

export interface ListClientesParams {
  nome?: string
  /** Busca multi-campo (nome/CPF/telefone/comércio) — PLAN-083 Fase 6. */
  q?: string
  page?: number
  limit?: number
  sort?: string
  order?: "asc" | "desc"
  /** Drill-down (PLAN-063/P13): admin/socio/super listam os clientes do operador-alvo. */
  usuarioId?: string
}

export interface PaginatedResponse<T> {
  data: T[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

export interface PaginatedResponse<T> {
  data: T[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

export interface DependabotPR {
  number: number
  title: string
  branch: string
}

export interface CreateGastoInput {
  valor: number
  categoria: string
  data: string
  observacao?: string
}

export interface ListGastosResult {
  data: GastoItem[]
  totalPeriodo: number
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

export interface SerieItem {
  data: string
  recebido: number
  previsto: number
}

export interface ResumoInsights {
  periodo: PeriodoInsight
  dataInicio: string
  dataFim: string
  serie: SerieItem[]
}

export interface CarteiraSnapshot {
  emAtraso: number
  aVencer: number
  pagas: number
  total: number
}

export interface GastoCategoria {
  categoria: string
  total: number
}

export interface ContribuicaoOperador {
  usuarioId: string
  nome: string
  recebido: number
}

export interface ResumoCarteira {
  carteira: CarteiraSnapshot
  gastosPorCategoria: GastoCategoria[]
  contribuicaoOperadores: ContribuicaoOperador[]
}

export interface CriarLeadResult {
  ok: boolean
  jaExistia?: boolean
  lead?: Lead
}

export interface ListarLeadsResult {
  data: Lead[]
  pagination: { page: number; limit: number; total: number; pages: number }
}

export interface CobrancaDoDiaResult {
  indicadores: {
    aReceberHoje: number
    recebidoHoje: number
    clientesParaCobrar: number
    atrasado: number
    aVencer: number
  }
  cobrancas: CobrancaItem[]
}

export interface ParcelaDoDia {
  numero: number
  valorPrevisto: number
  saldoPendente: number
}

export interface ParcelaHojeCliente {
  clienteId: string
  clienteNome: string
  contratoId: string
  parcelas: ParcelaDoDia[]
}

export interface RegistrarVisitaInput {
  clienteId: string
  contratoId: string
  tipo: "visitado" | "nao_localizado" | "promessa"
  dataPromessa?: string | null
}

export interface ResumoAtendidos {
  /** Clientes distintos atendidos (guarda-chuva: visitado + não encontrado + promessa + pagos). */
  total: number
  visitado: number
  naoEncontrado: number
  promessa: number
  pagos: number
}

export interface PagamentoParcela {
  id: string
  pagamentoId: string
  parcelaId: string
  valor: number
  /** Número da parcela quitada (ex.: 3). */
  numero?: number
}

export interface PagamentoComDetalhes extends Pagamento {
  parcelas: PagamentoParcela[]
  estornadoEm?: string | null
  estornadoPor?: string | null
  estornoMotivo?: string | null
}

export interface BlocoGpsInicial {
  coords: Localizacao | null
  estado: GpsEstado
  aviso: string | null
}

export interface ResultadoCaptura {
  localizacao: Localizacao
  endereco: Partial<EnderecoTexto>
  /** `reverse` = endereço preenchido pelo reverse geocode; `gps` = só coords (preencher manualmente). */
  origem: "reverse" | "gps"
}

export interface UseGeolocationReturn {
  capturando: boolean
  erro: string | null
  capturar: () => Promise<ResultadoCaptura | null>
}

export interface Localizacao {
  lat: number
  lng: number
}

export interface AlvoCliente {
  endereco: EnderecoTexto
  localizacao?: Localizacao | null
  enderecoComercio?: EnderecoTexto | null
  localizacaoComercio?: Localizacao | null
}

export interface SortableItem {
  situacao: "atrasado" | "venceHoje"
  clienteLat: number | null
  clienteLng: number | null
}

interface GeocodingResult {
  logradouro?: string
  numero?: string
  bairro?: string
  cidade?: string
  /** Código UF (2 letras, ex.: "SP") — preferido o ISO3166-2-lvl4 do Nominatim. */
  estado?: string
}

export type ResultadoAnexo =
  | { ok: true; nome: string; mime: string; tamanho: number; blob: Blob | null }
  | { ok: false; erro: ErroAnexo }

